let memoryProperties = null;

async function get100Properties() {
  if (memoryProperties && memoryProperties.length >= 100) return memoryProperties;
  try {
    const res = await fetch(GITHUB_100_URL, {
      headers: { 'User-Agent': 'TerraYield-Worker/2.0' },
      cf: { cacheTtl: 86400, cacheEverything: true }
    });
    if (res.ok) {
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        memoryProperties = data;
        return data;
      }
    }
  } catch (err) {
    console.error('Failed to fetch 100 properties from GitHub:', err);
  }
  return memoryProperties || SHOWCASE_FALLBACK;
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const { pathname } = url;

    const corsHeaders = {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, Authorization',
    };

    if (request.method === 'OPTIONS') {
      return new Response(null, { headers: corsHeaders });
    }

    // ── API Routes ──
    if (pathname === '/api/properties') {
      const props = await get100Properties();
      return Response.json(props, { headers: corsHeaders });
    }

    if (pathname.startsWith('/api/properties/')) {
      const id = pathname.replace('/api/properties/', '');
      const props = await get100Properties();
      const match = props.find(p => p.id === id);
      if (!match) {
        return new Response(JSON.stringify({ error: 'Property not found' }), {
          status: 404,
          headers: { 'Content-Type': 'application/json', ...corsHeaders },
        });
      }
      return Response.json(match, { headers: corsHeaders });
    }

    if (pathname === '/api/health') {
      const props = await get100Properties();
      return Response.json({
        status: 'healthy',
        app: 'TerraYield AI — Investment Property & Ag Intelligence Finder',
        domain: 'terrayeild.com / terrayield.com',
        indexed_properties: props.length,
        network: 'Cloudflare Edge Global Network',
      }, { headers: corsHeaders });
    }

    // ── Main Web Application HTML ──
    const initialProps = await get100Properties();
    return new Response(renderAntiStudioApp(initialProps), {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        ...corsHeaders,
      },
    });
  },
};

